SET
  @ExtractedSQLHash_aa249e805c8d = N'95d25ced120e41721dee5e985f62e99f323d5bef5d8099a8ae58cf5840811110'
SET
  @ExtractionStatus_aa249e805c8d = N'OK'
IF NOT EXISTS (SELECT 1 FROM [${mjSchema}].[Query]
               WHERE [ID] = @ID_aa249e805c8d
                  OR ([CategoryID] = @CategoryID_aa249e805c8d AND [Name] = @Name_aa249e805c8d))
